python - <<'PY'
import numpy as np
from PIL import Image
im=np.array(Image.open('/app/output/start_egocentric_mirrored_camera.jpg')).astype(int)
regions={'cube1':(410,95,480,200),'cube2':(530,130,590,215),'cube3':(420,195,480,270),'blue':(460,145,510,220),'red':(565,205,630,270),'yellow':(675,110,710,155),'green':(700,155,745,205)}
for name,(x0,y0,x1,y1) in regions.items():
 a=im[y0:y1,x0:x1]; mx=a.max(2); mn=a.min(2); sat=mx-mn
 mask=(sat>60)&(mx>40)
 # for solid blocks constrain hues
 if name=='blue': mask &= (a[:,:,2]>a[:,:,0]*1.35)&(a[:,:,2]>a[:,:,1]*1.2)
 if name=='red': mask &= (a[:,:,0]>a[:,:,1]*1.5)&(a[:,:,0]>a[:,:,2]*1.5)
 if name=='yellow': mask &= (a[:,:,0]>a[:,:,2]*1.25)&(a[:,:,1]>a[:,:,2]*1.25)
 if name=='green': mask &= (a[:,:,1]>a[:,:,0]*1.1)&(a[:,:,1]>a[:,:,2]*1.1)
 ys,xs=np.where(mask)
 if len(xs):
  print(name, 'n',len(xs),'bbox', (int(xs.min()+x0),int(ys.min()+y0),int(xs.max()+x0),int(ys.max()+y0)),'mean', (xs.mean()+x0,ys.mean()+y0))
